-- ── FileVariant ─────────────────────────────────────────────────────────────
ALTER TABLE public."FileVariant" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."FileVariant" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS file_variants_reward_image_read ON public."FileVariant";
CREATE POLICY file_variants_reward_image_read ON public."FileVariant"
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public."StoredFile" sf
      WHERE sf.id = "FileVariant"."fileId" AND sf.category = 'REWARD_IMAGE' AND sf.visibility = 'PUBLIC'
    )
  );
DROP POLICY IF EXISTS file_variants_read ON public."FileVariant";
CREATE POLICY file_variants_read ON public."FileVariant"
  FOR SELECT
  USING ((SELECT app_rls_bypass_on('FileVariant')) OR EXISTS (SELECT 1 FROM public."StoredFile" sf WHERE sf.id = "FileVariant"."fileId"));
DROP POLICY IF EXISTS file_variants_write ON public."FileVariant";
CREATE POLICY file_variants_write ON public."FileVariant"
  USING (
    (SELECT app_rls_bypass_on('FileVariant'))
    OR EXISTS (SELECT 1 FROM public."StoredFile" sf WHERE sf.id = "FileVariant"."fileId" AND (
      (sf."tenantId" IS NULL AND app_owns(sf."uploadedById"))
      OR (sf."tenantId" IS NOT NULL AND (
        (sf.category IN ('STORE_LOGO', 'STORE_BANNER') AND sf."tenantId" = ANY ((SELECT app_permitted_tenants('LOCATION', 'UPDATE'))::text[]))
        OR (sf.category = 'MERCHANT_KYB' AND sf."tenantId" = ANY ((SELECT app_permitted_tenants('KYB', 'UPDATE'))::text[]))
        OR (sf.category = 'REWARD_IMAGE' AND (sf."tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[]) OR sf."tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])))
        OR (sf.category = 'BROADCAST_IMAGE' AND sf."tenantId" = ANY ((SELECT app_permitted_tenants('BROADCAST', 'UPDATE'))::text[]))
      ))
    ))
  )
  WITH CHECK (
    (SELECT app_rls_bypass_on('FileVariant'))
    OR EXISTS (SELECT 1 FROM public."StoredFile" sf WHERE sf.id = "FileVariant"."fileId" AND (
      (sf."tenantId" IS NULL AND app_owns(sf."uploadedById"))
      OR (sf."tenantId" IS NOT NULL AND (
        (sf.category IN ('STORE_LOGO', 'STORE_BANNER') AND sf."tenantId" = ANY ((SELECT app_permitted_tenants('LOCATION', 'UPDATE'))::text[]))
        OR (sf.category = 'MERCHANT_KYB' AND sf."tenantId" = ANY ((SELECT app_permitted_tenants('KYB', 'UPDATE'))::text[]))
        OR (sf.category = 'REWARD_IMAGE' AND (sf."tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[]) OR sf."tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])))
        OR (sf.category = 'BROADCAST_IMAGE' AND sf."tenantId" = ANY ((SELECT app_permitted_tenants('BROADCAST', 'UPDATE'))::text[]))
      ))
    ))
  );

