  USING ((SELECT app_rls_bypass_on('Location')))
  WITH CHECK ((SELECT app_rls_bypass_on('Location')));
DROP POLICY IF EXISTS locations_insert ON public."Location";
CREATE POLICY locations_insert ON public."Location"
  FOR INSERT
  WITH CHECK ("tenantId" = ANY ((SELECT app_permitted_tenants('LOCATION', 'UPDATE'))::text[]) OR (SELECT app_rls_bypass_on('Location')));
DROP POLICY IF EXISTS locations_update ON public."Location";
CREATE POLICY locations_update ON public."Location"
  FOR UPDATE
  USING ("tenantId" = ANY ((SELECT app_permitted_tenants('LOCATION', 'UPDATE'))::text[]) OR (SELECT app_rls_bypass_on('Location')))
  WITH CHECK ("tenantId" = ANY ((SELECT app_permitted_tenants('LOCATION', 'UPDATE'))::text[]) OR (SELECT app_rls_bypass_on('Location')));
DROP POLICY IF EXISTS locations_terminal_lock ON public."Location";
