  FOR UPDATE
  USING ("tenantId" = ANY ((SELECT app_permitted_tenants('TERMINAL', 'CREATE'))::text[]) OR (SELECT app_rls_bypass_on('Location')))
  WITH CHECK ("tenantId" = ANY ((SELECT app_permitted_tenants('TERMINAL', 'CREATE'))::text[]) OR (SELECT app_rls_bypass_on('Location')));

