-- ── Reward ──────────────────────────────────────────────────────────────────
ALTER TABLE public."Reward" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Reward" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS rewards_system ON public."Reward";
CREATE POLICY rewards_system ON public."Reward"
  USING ((SELECT app_rls_bypass_on('Reward')))
  WITH CHECK ((SELECT app_rls_bypass_on('Reward')));
DROP POLICY IF EXISTS rewards_api_key_insert ON public."Reward";
CREATE POLICY rewards_api_key_insert ON public."Reward"
  FOR INSERT
  TO app_runtime
  WITH CHECK (app_api_key_org_access("tenantId"));
DROP POLICY IF EXISTS rewards_api_key_read ON public."Reward";
CREATE POLICY rewards_api_key_read ON public."Reward"
  FOR SELECT
  TO app_runtime
  USING (app_api_key_org_access("tenantId"));
DROP POLICY IF EXISTS rewards_api_key_update ON public."Reward";
CREATE POLICY rewards_api_key_update ON public."Reward"
  FOR UPDATE
  TO app_runtime
  USING (app_api_key_org_access("tenantId"))
  WITH CHECK (app_api_key_org_access("tenantId"));
DROP POLICY IF EXISTS rewards_read ON public."Reward";
CREATE POLICY rewards_read ON public."Reward"
  FOR SELECT
  USING (
    (SELECT app_rls_bypass_on('Reward'))
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'READ'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'PUBLISH'))::text[])
    OR app_shared('REWARD', id, 'VIEW')
    OR (
      "isDeleted" = false
      AND "rewardKind" = 'CONSUMER'
      AND status = 'PUBLISHED'
    )
    OR app_holds_reward_claim(id)
  );
DROP POLICY IF EXISTS rewards_write ON public."Reward";
CREATE POLICY rewards_write ON public."Reward"
  FOR INSERT
  WITH CHECK ("tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[]) OR (SELECT app_rls_bypass_on('Reward')));
DROP POLICY IF EXISTS rewards_update ON public."Reward";
CREATE POLICY rewards_update ON public."Reward"
  FOR UPDATE
  USING (
    (SELECT app_rls_bypass_on('Reward'))
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'PUBLISH'))::text[])
    OR app_shared('REWARD', id, 'EDIT')
  )
  WITH CHECK (
    (SELECT app_rls_bypass_on('Reward'))
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'PUBLISH'))::text[])
    OR app_shared('REWARD', id, 'EDIT')
  );

