    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'READ'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])
    OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'PUBLISH'))::text[])
    OR app_shared('REWARD', "rewardId", 'VIEW')
