ALTER TABLE public."StoredFile" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."StoredFile" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS stored_files_read ON public."StoredFile";
CREATE POLICY stored_files_read ON public."StoredFile"
  FOR SELECT
  USING ((SELECT app_rls_bypass_on('StoredFile')) OR (
      ("tenantId" IS NULL AND app_owns("uploadedById"))
      OR ("tenantId" IS NOT NULL AND (
        (category IN ('STORE_LOGO', 'STORE_BANNER') AND app_tenant_org_member("tenantId"))
        OR (category = 'MERCHANT_KYB' AND ("tenantId" = ANY ((SELECT app_permitted_tenants('KYB', 'READ'))::text[]) OR "tenantId" = ANY ((SELECT app_permitted_tenants('KYB', 'UPDATE'))::text[])))
        OR (category = 'REWARD_IMAGE' AND (
          "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'READ'))::text[])
          OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[])
          OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])
        ))
        OR (category = 'BROADCAST_IMAGE' AND ("tenantId" = ANY ((SELECT app_permitted_tenants('BROADCAST', 'READ'))::text[]) OR "tenantId" = ANY ((SELECT app_permitted_tenants('BROADCAST', 'UPDATE'))::text[])))
      ))
    ));
DROP POLICY IF EXISTS stored_files_write ON public."StoredFile";
CREATE POLICY stored_files_write ON public."StoredFile"
  USING ((SELECT app_rls_bypass_on('StoredFile')) OR (
      ("tenantId" IS NULL AND app_owns("uploadedById"))
      OR ("tenantId" IS NOT NULL AND (
        (category IN ('STORE_LOGO', 'STORE_BANNER') AND "tenantId" = ANY ((SELECT app_permitted_tenants('LOCATION', 'UPDATE'))::text[]))
        OR (category = 'MERCHANT_KYB' AND "tenantId" = ANY ((SELECT app_permitted_tenants('KYB', 'UPDATE'))::text[]))
        OR (category = 'REWARD_IMAGE' AND ("tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[]) OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])))
        OR (category = 'BROADCAST_IMAGE' AND "tenantId" = ANY ((SELECT app_permitted_tenants('BROADCAST', 'UPDATE'))::text[]))
      ))
    ))
  WITH CHECK ((SELECT app_rls_bypass_on('StoredFile')) OR (
      ("tenantId" IS NULL AND app_owns("uploadedById"))
      OR ("tenantId" IS NOT NULL AND (
        (category IN ('STORE_LOGO', 'STORE_BANNER') AND "tenantId" = ANY ((SELECT app_permitted_tenants('LOCATION', 'UPDATE'))::text[]))
        OR (category = 'MERCHANT_KYB' AND "tenantId" = ANY ((SELECT app_permitted_tenants('KYB', 'UPDATE'))::text[]))
        OR (category = 'REWARD_IMAGE' AND ("tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'CREATE'))::text[]) OR "tenantId" = ANY ((SELECT app_permitted_tenants('REWARD', 'UPDATE'))::text[])))
        OR (category = 'BROADCAST_IMAGE' AND "tenantId" = ANY ((SELECT app_permitted_tenants('BROADCAST', 'UPDATE'))::text[]))
      ))
    ));
DROP POLICY IF EXISTS stored_files_reward_image_read ON public."StoredFile";
CREATE POLICY stored_files_reward_image_read ON public."StoredFile"
  FOR SELECT
  USING (
    category = 'REWARD_IMAGE'
    AND visibility = 'PUBLIC'
    AND EXISTS (SELECT 1 FROM public."RewardImage" ri WHERE ri."fileId" = "StoredFile".id AND ri."isDeleted" = false)
  );
DROP POLICY IF EXISTS stored_files_api_key_read ON public."StoredFile";
CREATE POLICY stored_files_api_key_read ON public."StoredFile"
  FOR SELECT
  TO app_runtime
  USING ("tenantId" IS NOT NULL AND app_api_key_org_access("tenantId"));

