  FOR INSERT
  TO app_runtime
  WITH CHECK ((CASE WHEN "locationId" IS NULL THEN "tenantId" = ANY ((SELECT app_permitted_tenants('TERMINAL', 'CREATE'))::text[]) ELSE ("tenantId" || '|*') = ANY ((SELECT app_permitted_stores('TERMINAL', 'CREATE'))::text[]) OR ("tenantId" || '|' || "locationId") = ANY ((SELECT app_permitted_stores('TERMINAL', 'CREATE'))::text[]) END) OR (SELECT app_rls_bypass_on('TenantTerminal')));
DROP POLICY IF EXISTS tenant_terminals_update ON public."TenantTerminal";
CREATE POLICY tenant_terminals_update ON public."TenantTerminal"
  FOR UPDATE
  TO app_runtime
  USING ((CASE WHEN "locationId" IS NULL THEN "tenantId" = ANY ((SELECT app_permitted_tenants('TERMINAL', 'CREATE'))::text[]) ELSE ("tenantId" || '|*') = ANY ((SELECT app_permitted_stores('TERMINAL', 'CREATE'))::text[]) OR ("tenantId" || '|' || "locationId") = ANY ((SELECT app_permitted_stores('TERMINAL', 'CREATE'))::text[]) END) OR (SELECT app_rls_bypass_on('TenantTerminal')))
  WITH CHECK ((CASE WHEN "locationId" IS NULL THEN "tenantId" = ANY ((SELECT app_permitted_tenants('TERMINAL', 'CREATE'))::text[]) ELSE ("tenantId" || '|*') = ANY ((SELECT app_permitted_stores('TERMINAL', 'CREATE'))::text[]) OR ("tenantId" || '|' || "locationId") = ANY ((SELECT app_permitted_stores('TERMINAL', 'CREATE'))::text[]) END) OR (SELECT app_rls_bypass_on('TenantTerminal')));
