  USING ((CASE WHEN "locationId" IS NULL THEN "tenantId" = ANY ((SELECT app_permitted_tenants('TERMINAL', 'DELETE'))::text[]) ELSE ("tenantId" || '|*') = ANY ((SELECT app_permitted_stores('TERMINAL', 'DELETE'))::text[]) OR ("tenantId" || '|' || "locationId") = ANY ((SELECT app_permitted_stores('TERMINAL', 'DELETE'))::text[]) END) OR (SELECT app_rls_bypass_on('TenantTerminal')))
  WITH CHECK ((CASE WHEN "locationId" IS NULL THEN "tenantId" = ANY ((SELECT app_permitted_tenants('TERMINAL', 'DELETE'))::text[]) ELSE ("tenantId" || '|*') = ANY ((SELECT app_permitted_stores('TERMINAL', 'DELETE'))::text[]) OR ("tenantId" || '|' || "locationId") = ANY ((SELECT app_permitted_stores('TERMINAL', 'DELETE'))::text[]) END) OR (SELECT app_rls_bypass_on('TenantTerminal')));
