-- ── Policies no longer declared ─────────────────────────────────────────────
-- A policy on a listed table that table-policies.ts does not declare (renamed or removed) is dropped,
-- only when the session allows it (app.allow_policy_drops = 'on'); otherwise the apply fails and names them.
DO $$
DECLARE
  stale record;
  undeclared text[] := ARRAY[]::text[];
BEGIN
  FOR stale IN
    SELECT p.tablename, p.policyname FROM pg_catalog.pg_policies p
